INSERT INTO `wp_addonlibrary_addons` (`id`, `title`, `name`, `alias`, `addontype`, `description`, `ordering`, `templates`, `config`, `catid`, `is_active`, `test_slot1`, `test_slot2`, `test_slot3`) VALUES
(1,	'Woo Category Carousel',	'woocommerce_category_carousel_elementor',	'woocommerce_category_carousel',	'elementor',	'The Woo Category Carousel widget displays WooCommerce categories in a carousel format within Elementor, enhancing user interaction and category browsing experience.',	1,	'{\"html\":\"{% if rtl == \\\"false\\\" %}<div class=\\\"uc_overlay_image_carousel\\\"  style=\\\"direction:ltr;\\\"> {% endif %}\\n{% if rtl == \\\"true\\\" %}<div class=\\\"uc_overlay_image_carousel\\\"  style=\\\"direction:rtl;\\\"> {% endif %}\\n   <div class=\\\"uc_carousel owl-carousel owl-theme {{remote_parent.class}}\\\" id=\\\"{{uc_id}}\\\" {{remote_parent.attributes|raw}}>\\n     \\n   <!-- start item -->\\n   {% for term in woocommerce_categories %}\\n     {% if custom_image_field == \\\"true\\\" %}{% set image = ucfunc(\\\"get_term_image\\\",term.id,custom_image_field_name) %}{% endif %}\\n     {% if term.taxonomy == \\\"product_brand\\\" %}{% set woo_brand_image = ucfunc(\\\"get_term_image\\\",term.id,\\\"thumbnail_id\\\") %}{% endif %}\\n      \\n      {% if (show_with_images == \\\"false\\\") or (show_with_images == \\\"true\\\" and term.image) or (show_with_images == \\\"true\\\" and custom_image_field == \\\"true\\\" and image is not empty) or (term.taxonomy == \\\"product_brand\\\" and woo_brand_image is not empty ) %}\\n      <div class=\\\"uc_image_carousel_container_holder ue-item\\\">\\n        \\n            <div class=\\\"uc_image_carousel_placeholder\\\">\\n              <a href=\\\"{{term.link}}\\\" target=\\\"{{open_link_in_new_tab}}\\\">\\n\\n\\t\\t\\t\\t\\t{% if custom_image_field == \\\"false\\\" %}\\n                       {% if term.taxonomy == \\\"product_brand\\\" %}\\n                           {% if woo_brand_image is not empty %}\\n                             <div style=\\\"background-image:url({{ attribute(woo_brand_image, image_size) ?? woo_brand_image.image }});\\\" class=\\\"carousel-image\\\"><\\/div>\\n                           {% else %}\\n                             <div style=\\\"background-image:url({{fallback_image}});\\\" class=\\\"carousel-image\\\"><\\/div>\\n                           {% endif %}\\n                       {% else %}\\n                          {% if term.image is not empty %}\\n                            <div style=\\\"background-image:url({{ attribute(term, image_size) ?? term.image }});\\\" class=\\\"carousel-image\\\"><\\/div>\\n                          {% else %}\\n                            <div style=\\\"background-image:url({{fallback_image}});\\\" class=\\\"carousel-image\\\"><\\/div>\\n                          {% endif %}\\n                       {% endif %}\\n\\t\\t\\t\\t \\t{% else %}\\n                          {% if image is not empty %}    \\n                \\t\\t\\t\\t<div style=\\\"background-image:url({{image.thumb_large}});\\\" class=\\\"carousel-image\\\"><\\/div>\\n                          {% else %}\\n                              <div  class=\\\"carousel-image\\\"><\\/div>\\n                          {% endif %}    \\n                    {% endif %}\\n\\n\\t\\t\\t\\t<\\/a>\\n            <\\/div>\\n\\n            <div class=\\\"uc_image_carousel_content content-padding\\\">\\n              <div>\\n              {% if show_title == \\\"true\\\" or show_number_of_products == \\\"true\\\" %}{% if show_title == \\\"true\\\" %}<div class=\\\"uc_post_title\\\"><a href=\\\"{{term.link}}\\\" target=\\\"{{open_link_in_new_tab}}\\\">{% if category_characters_number is not empty %}{{term.name|truncate(category_characters_number)|raw}}{% else %}{{term.name|raw}}{% endif %}<\\/a>{% endif %}\\n\\t\\t\\t\\t{% if show_number_of_products == \\\"true\\\" %}\\n                               <span class=\\\"uc_cat_carousel_style_one_item_num_posts_spacer\\\"><\\/span>\\n                               <span class=\\\"uc_cat_carousel_style_one_item_num_posts\\\"><span class=\\\"text_before_num\\\">{{text_before_post_num|raw}}<\\/span>{{term.num_posts}}<span class=\\\"text_after_num\\\">{{text_after_post_num|raw}}<\\/span><\\/span>\\n                {% endif %}\\n              <\\/div>{% endif %}\\n              {% if show_intro == \\\"true\\\" %}<div class=\\\"uc_paragraph\\\" >{{term.description}}<\\/div>{% endif %}\\n              {% if show_button == \\\"true\\\" %}<a class=\\\"uc_more_btn\\\"  href=\\\"{{term.link}}\\\" target=\\\"{{open_link_in_new_tab}}\\\"><div class=\\\"ue-btn-inner-wrapper\\\">{{button_text|raw}}<div class=\\\"ue_btn_icon\\\">{{button_icon_html|raw}}<\\/div><\\/div><\\/a>{% endif %}\\n              <\\/div>\\n            <\\/div>\\n          <\\/div>\\n          {% endif %}\\n      \\n     {% endfor %}\\n     <!-- end item -->\\n     \\n   <\\/div>\\t\\n<\\/div>\",\"css\":\"#{{uc_id}} *{\\n  box-sizing:border-box;\\n}\\n.uc_carousel *\\n{\\n  transition: all {{transition_time}}s ease-in-out;\\n}\\n#{{uc_id}}{\\n  position:relative;\\n  min-height:1px;\\n}\\n.uc_post_grid_style_one .ue_taxonomy_image {\\n\\tbackground-color: white;\\n\\tpadding:16px;\\n}\\n.uc_post_grid_style_one .ue_taxonomy_image .uc-term-image{\\n\\twidth:100%;\\n\\theight:100%;\\n}\\n#{{uc_id}} .uc_post_title{\\n  font-size:21px;\\n}\\n{% if spacing_type == \\\"full\\\" %}\\n#{{uc_id}} .uc_post_title{\\n  width:100%;\\n  display:flex;\\n  align-items:center;\\n  justify-content:space-between;\\n}\\n{% endif %}\\n#{{uc_id}} .carousel-image{\\n  background-repeat: no-repeat;\\n}\\n\\n#{{uc_id}}  .owl-nav .owl-prev{\\n    position:absolute;\\n    display:inline-block;\\n    text-align:center;\\n}\\n#{{uc_id}} .owl-nav .owl-next{\\n  position:absolute;\\n  display:inline-block;\\n  text-align:center;\\n}\\n\\n#{{uc_id}} .owl-carousel .owl-nav .owl-prev:after{\\n    content: \\\"{{arrow_left|raw}}\\\";\\n}\\n#{{uc_id}} .owl-carousel .owl-nav .owl-next:after{\\n    content: \\\"{{arrow_right|raw}}\\\";\\n}\\n\\n#{{uc_id}} .uc_image_carousel_container_holder{\\n  text-align:{{text_align}};\\n  overflow:hidden;\\n}\\n\\n#{{uc_id}} .uc_more_bt